local preds6954 = [0.9,0.8,0.7,0.6,0.5,0.4,0.3,0.2]
local labels6954 = [1,1,0,1,0,0,0,0]
local prPoints = []
for (i: 1 .. preds6954.listLen()) {
  local tp = 0
  local fp = 0
  local fn = 0
  for (j: 1 .. preds6954.listLen()) {
    if (preds6954[j] >= preds6954[i]) {
      if (labels6954[j] == 1) { tp = tp+1 } else { fp = fp+1 }
    } else {
      if (labels6954[j] == 1) { fn = fn+1 }
    }
  }
  local prec = if (tp+fp > 0) tp/(tp+fp) else 1
  local rec = if (tp+fn > 0) tp/(tp+fn) else 0
  prPoints.add([rec, prec])
}
prPoints.sort { a, b -> a[1] < b[1] }
local aucpr = 0
for (i: 1 .. prPoints.listLen()-1) {
  aucpr = aucpr + (prPoints[i+1][1]-prPoints[i][1]) * (prPoints[i][2]+prPoints[i+1][2]) / 2
}
println(formatDecimal(abs(aucpr), 4))

